// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0 && _tos.length <= 50);

        // Track the selector that will be used by encoding the call
        bytes4 expectedSelector = bytes4(keccak256("transferFrom(address,address,uint256)"));

        // We need to check what selector is used. Since we can't read internal state,
        // we'll check the behavior: if the contract uses safeTransferFrom, it will fail
        // when calling a simple contract that only has transferFrom

        // Deploy a minimal mock that only accepts transferFrom
        MockTransferFrom mock = new MockTransferFrom();

        // Call transfer with the mock's address
        (bool success, ) = address(c).call(
            abi.encodeWithSignature(
                "transfer(address,address,address[],uint256)",
                from, address(mock), _tos, v
            )
        );

        // The reference contract should succeed (uses correct transferFrom selector)
        assertTrue(success, "Reference contract should succeed with transferFrom-only mock");
    }
}

contract MockTransferFrom {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    // Fallback to catch unexpected calls
    fallback() external {
        revert("Unexpected function called");
    }
}

